correctCode.cpp:
int findMax(int arr[], int n) {
    if (n == 0) return -1;
    int maxVal = arr[0]; // Initialize with first element
    for(int i = 1; i < n; i++) {
        if (arr[i] > maxVal) maxVal = arr[i];
    }
    return maxVal;
}

